+/** Theoretical sales use and all actual consumption, by item and inclusive UTC days. */
+export function varianceReport(store, from, to) {
+  const totals = new Map();
+  const add = (itemId, field, qty) => {
+    if (!totals.has(itemId)) totals.set(itemId, { itemId, theoretical: 0, actual: 0 });
+    const line = totals.get(itemId);
+    line[field] = Math.round((line[field] + qty) * 1000) / 1000;
+  };
+  for (const sale of store.data.sales) {
+    const day = sale.soldAt.slice(0, 10);
+    if (day < from || day > to) continue;
+    for (const ingredient of sale.ingredients) add(ingredient.itemId, "theoretical", ingredient.qty);
+  }
+  for (const movement of store.data.movements) {
+    if (movement.type !== "consume" || movement.qty <= 0) continue;
+    const day = new Date(movement.at).toISOString().slice(0, 10);
+    if (day < from || day > to) continue;
+    const batch = store.data.batches.find((b) => b.id === movement.batchId);
+    if (batch) add(batch.itemId, "actual", movement.qty);
+  }
+  return [...totals.values()]
+    .filter((line) => line.theoretical > 0 || line.actual > 0)
+    .map((line) => ({ ...line, variance: Math.round((line.actual - line.theoretical) * 1000) / 1000 }))
+    .sort((a, b) => a.itemId - b.itemId);
+}
