+import { AppError } from "../errors.js";
+import { t } from "../i18n/messages.js";
+import { memoryStore } from "../db/store.js";
+import { getDish } from "./menu.js";
+import { getRecipe, scaled } from "./recipes.js";
+import { consume } from "./batches.js";
+
+/** Imports validated sales atomically, skipping tickets already recorded. */
+export function importSales(store, rows) {
+  const staged = memoryStore(store.data);
+  const existing = new Set(staged.data.sales.map((sale) => sale.ticket));
+  const tickets = new Set();
+  let dishes = 0;
+  for (const row of rows) {
+    try {
+      const dish = getDish(staged, row.dishId);
+      const recipe = getRecipe(staged, dish.recipeId);
+      if (existing.has(row.ticket)) continue;
+      const ingredients = scaled(recipe, row.qty);
+      for (const ingredient of ingredients) {
+        if (!Number.isFinite(ingredient.qty) || ingredient.qty < 0)
+          throw new AppError("invalid_qty");
+        if (ingredient.qty > 0)
+          consume(staged, ingredient.itemId, ingredient.qty, { at: row.soldAt, ref: `sale:${row.ticket}` });
+      }
+      staged.data.sales.push({
+        id: staged.nextId("sale"), ticket: row.ticket, soldAt: row.soldAt,
+        dishId: row.dishId, qty: row.qty, ingredients,
+      });
+      tickets.add(row.ticket);
+      dishes += row.qty;
+    } catch (error) {
+      if (!(error instanceof AppError)) throw error;
+      throw new AppError("bad_request", { reason: `row ${row.row}: ${t(error.code, "en", error.params)}` });
+    }
+  }
+  store.data = staged.data;
+  return { tickets: tickets.size, dishes };
+}
