diff --git a/src/io/sales-import.js b/src/io/sales-import.js
new file mode 100644
index 0000000..e7481b9
--- /dev/null
+++ b/src/io/sales-import.js
@@ -0,0 +1,37 @@
+import { AppError } from "../errors.js";
+import { isDate } from "../dates.js";
+import { importSales } from "../domain/sales.js";
+import { parseCsv } from "./csv.js";
+
+/** Validates a till CSV and imports every new ticket atomically. */
+export function importSalesCsv(store, text) {
+  if (typeof text !== "string") throw new AppError("bad_request", { reason: "csv must be text" });
+  // Check quoting explicitly: the shared CSV reader is intentionally permissive.
+  let row = 1;
+  for (const line of text.split(/\r?\n/)) {
+    if (!line.trim()) continue;
+    if (!/^(?:"(?:[^"]|"")*"|[^",]*)(?:,(?:"(?:[^"]|"")*"|[^",]*))*$/.test(line))
+      throw new AppError("bad_request", { reason: `row ${row}: malformed CSV` });
+    row++;
+  }
+  const [header = [], ...records] = parseCsv(text);
+  const keys = header.map((key) => key.trim());
+  const columns = ["ticket", "soldAt", "dishId", "qty"];
+  if (keys.length !== columns.length || columns.some((key) => !keys.includes(key)))
+    throw new AppError("bad_request", { reason: "row 1: expected columns ticket,soldAt,dishId,qty" });
+  const rows = records.map((fields, i) => {
+    const fail = (reason) => { throw new AppError("bad_request", { reason: `row ${i + 2}: ${reason}` }); };
+    if (fields.length !== keys.length) fail("wrong number of columns");
+    const values = Object.fromEntries(keys.map((key, j) => [key, fields[j].trim()]));
+    if (!values.ticket) fail("ticket is required");
+    const instant = /^(\d{4}-\d{2}-\d{2})T(?:[01]\d|2[0-3]):[0-5]\d:[0-5]\d(?:\.\d+)?(?:Z|[+-](?:[01]\d|2[0-3]):[0-5]\d)$/;
+    if (!instant.test(values.soldAt) || !isDate(values.soldAt.slice(0, 10)) || !Number.isFinite(Date.parse(values.soldAt)))
+      fail("soldAt must be an ISO instant");
+    const dishId = Number(values.dishId);
+    const qty = Number(values.qty);
+    if (!/^\d+$/.test(values.dishId) || !Number.isSafeInteger(dishId) || dishId < 1) fail("invalid dishId");
+    if (!/^\d+$/.test(values.qty) || !Number.isSafeInteger(qty) || qty < 1) fail("invalid qty");
+    return { ticket: values.ticket, soldAt: new Date(values.soldAt).toISOString(), dishId, qty, row: i + 2 };
+  });
+  return importSales(store, rows);
+}
